#include <boost/asio/spawn.hpp>
#include <cstdlib>
#include <functional>
#include <iostream>
#include <string>
#include <webcpp/beast/core.hpp>

namespace beast = webcpp::beast;         // from <webcpp/beast.hpp>
namespace http = beast::http;            // from <webcpp/beast/http.hpp>
namespace websocket = beast::websocket;  // from <webcpp/beast/websocket.hpp>
namespace net = boost::asio;             // from <boost/asio.hpp>
using tcp = webcpp::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

//------------------------------------------------------------------------------

// Report a failure
namespace {
void fail(beast::error_code ec, char const* what) {
    std::cerr << what << ": " << ec.message() << "\n";
}

// Sends a WebSocket message and prints the response
void do_session(std::string host, std::string const& port, std::string const& text,
                // Value parameters retain the upstream callback and coroutine ownership contract.
                // NOLINTNEXTLINE(performance-unnecessary-value-param)
                webcpp::asio::io_context& ioc, net::yield_context yield) {
    beast::error_code ec;

    // These objects perform our I/O
    tcp::resolver resolver(ioc);
    websocket::stream<beast::tcp_stream> ws(ioc);

    // Look up the domain name
    auto const results = resolver.async_resolve(host, port, yield[ec]);
    if (ec) {
        {
            fail(ec, "resolve");
            return;
        }
    }

    // Set a timeout on the operation
    beast::get_lowest_layer(ws).expires_after(std::chrono::seconds(30));

    // Make the connection on the IP address we get from a lookup
    auto const ep = beast::get_lowest_layer(ws).async_connect(results, yield[ec]);
    if (ec) {
        {
            fail(ec, "connect");
            return;
        }
    }

    // Update the host_ string. This will provide the value of the
    // Host HTTP header during the WebSocket handshake.
    // See https://tools.ietf.org/html/rfc7230#section-5.4
    host += ':' + std::to_string(ep.port());

    // Turn off the timeout on the tcp_stream, because
    // the websocket stream has its own timeout system.
    beast::get_lowest_layer(ws).expires_never();

    // Set suggested timeout settings for the websocket
    ws.set_option(websocket::stream_base::timeout::suggested(beast::role_type::client));

    // Set a decorator to change the User-Agent of the handshake
    ws.set_option(websocket::stream_base::decorator([](websocket::request_type& req) {
        req.set(http::field::user_agent,
                std::string(BOOST_BEAST_VERSION_STRING) + " websocket-client-coro");
    }));

    // Perform the websocket handshake
    ws.async_handshake(host, "/", yield[ec]);
    if (ec) {
        {
            fail(ec, "handshake");
            return;
        }
    }

    // Send the message
    ws.async_write(net::buffer(std::string(text)), yield[ec]);
    if (ec) {
        {
            fail(ec, "write");
            return;
        }
    }

    // This buffer will hold the incoming message
    beast::flat_buffer buffer;

    // Read a message into our buffer
    ws.async_read(buffer, yield[ec]);
    if (ec) {
        {
            fail(ec, "read");
            return;
        }
    }

    // Close the WebSocket connection
    ws.async_close(websocket::close_code::normal, yield[ec]);
    if (ec) {
        {
            fail(ec, "close");
            return;
        }
    }

    // If we get here then the connection is closed gracefully

    // The make_printable() function helps print a ConstBufferSequence
    std::cout << beast::make_printable(buffer.data()) << '\n';
}

//------------------------------------------------------------------------------

}  // namespace

// The process entry point retains the standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int main(int argc, char** argv) {
    // Check command line arguments.
    if (argc != 4) {
        std::cerr << "Usage: websocket-client-coro <host> <port> <text>\n"
                  << "Example:\n"
                  << "    websocket-client-coro echo.websocket.org 80 \"Hello, world!\"\n";
        return EXIT_FAILURE;
    }
    auto const* const host = argv[1];
    auto const* const port = argv[2];
    auto const* const text = argv[3];

    // The io_context is required for all I/O
    webcpp::asio::io_context ioc;

    // Launch the asynchronous operation
    boost::asio::spawn(ioc,
                       // The concrete bound signature selects the upstream Asio spawn/completion
                       // overload. NOLINTNEXTLINE(modernize-avoid-bind)
                       std::bind(&do_session, std::string(host), std::string(port),
                                 std::string(text), std::ref(ioc), std::placeholders::_1),
                       // on completion, spawn will call this function
                       // Value parameters retain the upstream callback and coroutine ownership
                       // contract. NOLINTNEXTLINE(performance-unnecessary-value-param)
                       [](std::exception_ptr ex) {
                           // if an exception occurred in the coroutine,
                           // it's something critical, e.g. out of memory
                           // we capture normal errors in the ec
                           // so we just rethrow the exception here,
                           // which will cause `ioc.run()` to throw // lint-run: drives the
                           // application's network operations
                           if (ex) {
                               std::rethrow_exception(ex);
                           }
                       });

    // Run the I/O service. The call will return when
    // the socket is closed.
    ioc.run();  // lint-run: drives the application's network operations

    return EXIT_SUCCESS;
}
